function translatedLibrary() {
  const page = libraryPages.find((item) => item.id === "components/library");
  const sourceText = 'Usar nome acessível e HTML semântico. Foco visível, textos dinâmicos e suporte a dir="rtl".';
  const targetText = 'Use an accessible name and semantic HTML. Visible focus, dynamic text and support for dir="rtl".';
  const sourceOverlay = 'Dialog e Drawer usam dialog.showModal: foco contido nativo, Escape, restauração de foco. Tooltip abre em foco/hover, fecha por Escape; Popover fecha por Escape ou clique externo.';
  const targetOverlay = 'Dialog and Drawer use dialog.showModal: native focus containment, Escape and focus restoration. Tooltip opens on focus or hover and closes on Escape; Popover closes on Escape or an outside click.';
  if (!page || !page.sections.length || page.sections.some((section) => (!section.html.includes(sourceText) && !section.html.includes(sourceOverlay)) || !section.html.includes('<pre tabindex="0"><code>'))) return undefined;
  const combined = page.sections.map((section) => section.html).join("\n");
  const replacements = componentTranslations["components/catalog"];
  if (replacements.some(([source]) => !combined.includes(source))) return undefined;
  return page.sections.map((section) => {
    let html = section.html.replaceAll(sourceText, targetText).replaceAll(sourceOverlay, targetOverlay);
    for (const [source, target] of replacements) html = html.replaceAll(source, target);
    return { ...section, html };
  });
}
